export function assertProviderWorkTaskGraph(tasks:ProviderWorkTaskDefinition[]):void{const ids=new Set(tasks.map(x=>x.taskId));if(tasks.length!==14||ids.size!==14||PROVIDER_WORK_TASK_IDS.some(id=>!ids.has(id)))throw new Error("Provider work graph omits or duplicates a required task.");for(const task of tasks)if(task.prerequisites.some(x=>!ids.has(x)||x===task.taskId))throw new Error("Provider work graph has an unknown or self dependency.");const visiting=new Set<string>(),done=new Set<string>(),visit=(id:string)=>{if(visiting.has(id))throw new Error("Provider work graph contains a dependency cycle.");if(done.has(id))return;visiting.add(id);tasks.find(x=>x.taskId===id)!.prerequisites.forEach(visit);visiting.delete(id);done.add(id)};tasks.forEach(x=>visit(x.taskId))}
